#pragma once
#include <cstdint>
namespace ks {
// Copy the live patch's eight global-control bytes in firmware order, publish
// its pedal configuration into the selected part, then select its DSP route.
class GlobalSetupTask final{public:
 enum class Stage{DispatchControl,AwaitControl,ReadPatch,CaptureSource,LocateSource,LocateDestination,SetRemaining,ReadMirror,WriteMirror,TickDestination,TickRemaining,AdmitRemaining,DispatchPart,AwaitPart,ReadPedal,WritePedal,DispatchRoute,AwaitRoute,Complete};
 enum class Read{Patch,Mirror,Pedal};enum class Write{Mirror,Pedal};enum class Child{None,Control,Part,Route};
 Stage stage()const{return stage_;}uint8_t control()const{return control_;}uint8_t part()const{return part_;}uint32_t patch()const{return patch_;}uint8_t index()const{return index_;}uint8_t value()const{return value_;}uint8_t remaining()const{return remaining_;}
 Child child()const{switch(stage_){case Stage::AwaitControl:return Child::Control;case Stage::AwaitPart:return Child::Part;case Stage::AwaitRoute:return Child::Route;default:return Child::None;}}
 bool resumeChild(uint8_t handle=0){switch(stage_){case Stage::AwaitControl:control_=handle;stage_=Stage::ReadPatch;return true;case Stage::AwaitPart:part_=handle;stage_=Stage::ReadPedal;return true;case Stage::AwaitRoute:stage_=Stage::Complete;return true;default:return false;}}
 template<class StoreClock>unsigned nextClocks(StoreClock&&store)const{switch(stage_){case Stage::DispatchControl:case Stage::DispatchPart:case Stage::DispatchRoute:return 20;case Stage::ReadPatch:return 21;case Stage::LocateSource:case Stage::LocateDestination:return 9;case Stage::SetRemaining:return 6;case Stage::ReadMirror:return 8;case Stage::WriteMirror:return 3+store(Write::Mirror);case Stage::ReadPedal:return 15;case Stage::WritePedal:return 12+store(Write::Pedal);case Stage::AwaitControl:case Stage::AwaitPart:case Stage::AwaitRoute:case Stage::Complete:return 0;default:return 3;}}
 template<class Reader,class Writer,class StoreClock>unsigned advanceBefore(unsigned available,Reader&&read,Writer&&write,StoreClock&&store){unsigned used=0;while(auto cost=nextClocks(store)){if(cost>available-used)break;switch(stage_){case Stage::DispatchControl:stage_=Stage::AwaitControl;break;case Stage::ReadPatch:patch_=read(Read::Patch);stage_=Stage::CaptureSource;break;case Stage::CaptureSource:stage_=Stage::LocateSource;break;case Stage::LocateSource:index_=0;stage_=Stage::LocateDestination;break;case Stage::LocateDestination:stage_=Stage::SetRemaining;break;case Stage::SetRemaining:remaining_=8;stage_=Stage::ReadMirror;break;case Stage::ReadMirror:value_=uint8_t(read(Read::Mirror));stage_=Stage::WriteMirror;break;case Stage::WriteMirror:write(Write::Mirror,value_);stage_=Stage::TickDestination;break;case Stage::TickDestination:++index_;stage_=Stage::TickRemaining;break;case Stage::TickRemaining:--remaining_;stage_=Stage::AdmitRemaining;break;case Stage::AdmitRemaining:stage_=remaining_?Stage::ReadMirror:Stage::DispatchPart;break;case Stage::DispatchPart:stage_=Stage::AwaitPart;break;case Stage::ReadPedal:value_=uint8_t(read(Read::Pedal));stage_=Stage::WritePedal;break;case Stage::WritePedal:write(Write::Pedal,value_);stage_=Stage::DispatchRoute;break;case Stage::DispatchRoute:stage_=Stage::AwaitRoute;break;default:break;}used+=cost;}return used;}
private:Stage stage_=Stage::DispatchControl;uint8_t control_=0,part_=0,index_=0,remaining_=0,value_=0;uint32_t patch_=0;
};}
